import{_ as t,o as a,c as r,ai as o}from"./chunks/framework.Cg3BiOJh.js";const m=JSON.parse('{"title":"Validator & CI","description":"","frontmatter":{"title":"Validator & CI"},"headers":[],"relativePath":"validator/index.md","filePath":"validator/index.md","lastUpdated":1786775408000}'),i={name:"validator/index.md"};function n(l,e,s,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<p>The repository ships with validators and workflows that enforce protocol structure across generated assets, runtime operations, MCP discovery, transcripts, skill/plugin packaging, and docs.</p><h2 id="vpp-runtime-contract" tabindex="-1">VPP runtime contract <a class="header-anchor" href="#vpp-runtime-contract" aria-label="Permalink to &quot;VPP runtime contract&quot;">​</a></h2><ul><li><code>npm run check:generated</code> rejects drift from the v1.5 manifest.</li><li><code>npm run typecheck</code> verifies the typed core, host adapter, MCP server, and Worker.</li><li><code>npm run test:vpp</code> covers transitions, global counters, cycles, repair, OpenAPI operations, and 2025-era MCP discovery.</li><li><code>npm run validate:vpp-artifacts</code> checks the portable skill and plugin package.</li><li><code>npm run check:plugin-package</code> rejects stale downloadable plugin and standalone skill archives.</li><li><code>npm run build:worker</code> performs a Cloudflare dry-run build without deploying.</li></ul><h2 id="markdown-linting" tabindex="-1">Markdown linting <a class="header-anchor" href="#markdown-linting" aria-label="Permalink to &quot;Markdown linting&quot;">​</a></h2><ul><li>Command: <code>npm run lint:md</code></li><li>Scope: Human-authored documentation; generated specifications are excluded from style rewrites.</li><li>Purpose: Keep formatting predictable for both human readers and downstream tooling that ingests the spec.</li></ul><h2 id="spell-checking" tabindex="-1">Spell checking <a class="header-anchor" href="#spell-checking" aria-label="Permalink to &quot;Spell checking&quot;">​</a></h2><ul><li>Command: <code>npx cspell --no-progress &quot;docs/**/*.md&quot; &quot;spec/**/*.md&quot; &quot;website/docs/**/*.md&quot; &quot;README.md&quot;</code></li><li>Scope: Human-facing docs and machine-readable specs.</li><li>Purpose: Guard against typos in tag names, modifiers, and experiment identifiers that would otherwise break scripts.</li></ul><h2 id="transcript-validation" tabindex="-1">Transcript validation <a class="header-anchor" href="#transcript-validation" aria-label="Permalink to &quot;Transcript validation&quot;">​</a></h2><ul><li>Command: <code>node scripts/test-transcripts.mjs</code></li><li>Scope: Fixtures in <code>/tests/</code> and <code>/corpus/</code>.</li><li>Purpose: Ensure transcripts respect the command-line grammar and footer schema before they enter the corpus.</li></ul><h2 id="experiment-harnesses" tabindex="-1">Experiment harnesses <a class="header-anchor" href="#experiment-harnesses" aria-label="Permalink to &quot;Experiment harnesses&quot;">​</a></h2><ul><li>Location: <a href="https://github.com/cbassuarez/viable-prompt-protocol/tree/main/experiments" target="_blank" rel="noreferrer"><code>/experiments/</code></a></li><li>Scripts: <code>npm run run:exp1-protret</code>, <code>npm run run:exp2-promptinj</code>, <code>npm run run:exp1b-user-only</code>, and associated analyzers.</li><li>Purpose: Provide reproducible prompt-injection and retention studies grounded in the current protocol release.</li></ul><h2 id="pages-deployment" tabindex="-1">Pages deployment <a class="header-anchor" href="#pages-deployment" aria-label="Permalink to &quot;Pages deployment&quot;">​</a></h2><ul><li>Workflow: <code>.github/workflows/pages.yml</code></li><li>Steps: Install Node 20, run lint + spell + parser checks, build the VitePress site with <code>npm run docs:build</code>, and publish via <code>actions/deploy-pages</code>.</li><li>Output: <a href="https://viableprompt.org/" target="_blank" rel="noreferrer">https://viableprompt.org/</a></li></ul><p>Use these commands locally before pushing changes; CI will block merges that diverge from the expected outputs.</p>',14)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
